const SCHOOL_LOGO = 'data:image/png;base64,';
'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4z M20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-3h3z',edit:'M16 3l5 5-12 12H4v-5z M13 6l5 5',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',check:'M5 12l4 4L20 5',upload:'M12 16V3 M7 8l5-5 5 5 M3 15v6h18v-6',download:'M12 3v13 M7 11l5 5 5-5 M3 17v4h18v-4',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M14 3a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-4 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',room:'M3 21h18 M5 21V3h14v18 M9 7h2 M14 7h1 M9 11h2 M14 11h1 M10 21v-6h4v6',key:'M14 10l8 8-3 3-3-3-2 2-3-3 M15 7A6 6 0 1 1 3 7a6 6 0 0 1 12 0',logout:'M9 3H3v18h6 M9 12h12 M16 7l5 5-5 5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',chevron:'M9 5l7 7-7 7',info:'M12 11v6 M12 7v.1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',save:'M4 3h13l4 4v14H3V3z M7 3v7h10V3 M7 21v-7h10v7',print:'M6 9V3h12v6 M6 18H3V9h18v9h-3 M6 14h12v8H6z',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',menu:'M3 6h18 M3 12h18 M3 18h18',plus:'M12 4v16 M4 12h16',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',cloud:'M6 18a5 5 0 0 1 0-10 6 6 0 0 1 12-1 5 5 0 0 1 0 11 M9 15l3-3 3 3 M12 12v9',chart:'M4 21V10h4v11 M10 21V3h4v18 M16 21V7h4v14',close:'M5 5l14 14 M5 19L19 5'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const NATIVE_GAS=typeof google!=='undefined'&&google.script&&google.script.run;
const GAS=NATIVE_GAS || window.HTB_CONFIG?.mode==='live';
const DEFAULT='Htb12345@';
const defaultConfig={years:['2026 - 2027'],periods:['Giữa HK1','HK1','Giữa HK2','HK2'],subjects:['Toán','Ngữ văn','Tiếng Anh','Vật lý','Hóa học','Sinh học','Lịch sử','Địa lý','GD Kinh tế và Pháp luật','Tin học','Công nghệ','GD Quốc phòng và An ninh','Giáo dục thể chất']};
const S={token:'',user:null,config:structuredClone(defaultConfig),year:'2026 - 2027',period:'Giữa HK1',page:'entry',data:{records:[],mappings:[],roster:[]},record:null,dirty:false,filters:{grade:'',subject:'',room:'',className:''},importRows:[],importKind:'',users:[],busy:false};
let demoDB;
function demoInit(){try{demoDB=JSON.parse(localStorage.getItem('htb-demo-v1'));}catch{}if(!demoDB){demoDB={config:structuredClone(defaultConfig),users:[{phone:'0900000001',name:'Nguyễn Minh Anh',role:'teacher',mustChange:true,active:true},{phone:'0900000002',name:'Quản trị viên',role:'admin',mustChange:true,active:true}],mappings:[],roster:[],records:[],audit:[]};['Toán','Ngữ văn','Tiếng Anh'].forEach((subject,j)=>{[10,11,12].forEach(grade=>{for(let room=1;room<=2;room++){const m={year:S.year,period:S.period,grade:String(grade),subject,room:String(room).padStart(2,'0'),phach:`${grade}${j+1}${String(room).padStart(2,'0')}`};m.id=recordKey(m);demoDB.mappings.push(m);for(let stt=1;stt<=30;stt++)demoDB.roster.push({...m,id:m.id+'|'+stt,stt,studentId:`HS${grade}${room}${String(stt).padStart(2,'0')}`,name:`Học sinh minh họa ${String(stt).padStart(2,'0')}`,className:`${grade}A${String(room).padStart(2,'0')}`});}});});demoPersist();}}
function demoPersist(){localStorage.setItem('htb-demo-v1',JSON.stringify(demoDB));}
function recordKey(p){return [p.year,p.period,p.grade,p.subject,p.phach].join('|');}
async function digest(s){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');}
function isAdmin(){return S.user?.role==='admin';}
function scoped(a){return a.filter(x=>x.year===S.year&&x.period===S.period);}
function scoreValue(v){if(v===''||v===null||v===undefined)return null;const s=String(v).trim();if(!/^\d{1,2}([.,]\d{1,2})?$/.test(s)||Number(s.replace(',','.'))>10)throw Error('Điểm từ 0–10, tối đa 2 chữ số thập phân.');return Number(s.replace(',','.'));}
function validPassword(p){return p.length>=10&&p.length<=128&&/[a-z]/.test(p)&&/[A-Z]/.test(p)&&/\d/.test(p)&&/[\W_]/.test(p)&&p!==DEFAULT;}
function publicUser(u){return {phone:u.phone,name:u.name,role:u.role,mustChange:u.mustChange,active:u.active};}
async function demoApi(action,p){
 let u=demoDB.users.find(u=>u.phone===S.user?.phone);
 if(action==='login'){u=demoDB.users.find(u=>u.phone===p.phone&&u.active);if(!u||(u.password?await digest(p.password)!==u.password:p.password!==DEFAULT))throw Error('SĐT hoặc mật khẩu không đúng.');return {token:'demo-session',user:publicUser(u)};}
 if(action==='logout')return true;
 if(!u)throw Error('Hãy đăng nhập lại.');
 if(action==='changePassword'){if(u.password?await digest(p.oldPassword)!==u.password:p.oldPassword!==DEFAULT)throw Error('Mật khẩu hiện tại không đúng.');if(!validPassword(p.newPassword)||p.newPassword===p.oldPassword)throw Error('Mật khẩu mới chưa đủ yêu cầu.');u.password=await digest(p.newPassword);u.mustChange=false;demoPersist();return publicUser(u);}
 if(action==='bootstrap')return {user:publicUser(u),config:demoDB.config,connected:false};
 if(action==='list')return {records:scoped(demoDB.records).filter(x=>isAdmin()||x.owner===u.phone),mappings:scoped(demoDB.mappings),roster:isAdmin()?scoped(demoDB.roster):[]};
 if(action==='loadRecord'){const r=demoDB.records.find(x=>x.id===p.id);if(!r||(!isAdmin()&&r.owner!==u.phone))throw Error('Không có quyền xem phiếu.');return structuredClone(r);}
 if(action==='saveRecord'){
 const id=recordKey(p),old=demoDB.records.find(x=>x.id===id),map=demoDB.mappings.find(x=>x.id===id);if(!map)throw Error('Số phách chưa được khai báo cho khối và môn này.');if(old&&old.owner!==u.phone)throw Error('Phiếu thuộc một giám khảo khác.');if(old?.status==='confirmed')throw Error('Phiếu đã xác nhận, cần quản trị viên mở lại.');if(old&&(p.version||0)!==old.version)throw Error('Phiếu đã thay đổi. Vui lòng tải lại.');if(!p.date)throw Error('Chọn ngày kiểm tra.');
 const rows=p.rows.map((r,i)=>({stt:i+1,score:scoreValue(r.score),note:r.note}));if(!rows.some(r=>r.score!==null))throw Error('Cần nhập ít nhất một điểm để lưu.');
 const r={...p,id,rows,room:map.room,owner:u.phone,teacher:u.name,status:p.confirm?'confirmed':'draft',digitalSignature:false,version:(old?.version||0)+1,updatedAt:new Date().toISOString()};delete r.token;demoDB.records=demoDB.records.filter(x=>x.id!==id).concat(r);demoDB.audit.push({time:r.updatedAt,actor:u.phone,action:p.confirm?'Xác nhận bằng chữ ký ảnh':'Lưu phiếu',detail:{id,version:r.version}});demoPersist();return r;
 }
 if(!isAdmin())throw Error('Chỉ quản trị viên có quyền thực hiện.');
 if(action==='users')return demoDB.users.map(publicUser);
 if(action==='addConfig'){if(demoDB.config[p.type].includes(p.value))throw Error('Mục này đã có.');demoDB.config[p.type].push(p.value);demoPersist();return demoDB.config;}
 if(action==='import'){const checked=validateImport(p.kind,p.rows);if(checked.errors.length)throw Error(checked.errors[0]);const seen=new Set(),items=[];for(const r of p.rows){let d;if(p.kind==='users'){d={phone:String(r['SĐT']).trim(),name:r['Họ tên'],role:r['Vai trò'],active:true,mustChange:true};if(demoDB.users.some(x=>x.phone===d.phone))throw Error('SĐT đã tồn tại: '+d.phone);}
 else{d={year:S.year,period:S.period,grade:String(r['Khối']),subject:r['Môn'],room:String(r['Phòng'])};if(p.kind==='mappings'){d.phach=String(r['Số phách']);d.id=recordKey(d);if(demoDB.mappings.some(x=>x.id===d.id||x.year===d.year&&x.period===d.period&&x.grade===d.grade&&x.subject===d.subject&&x.room===d.room))throw Error('Phách hoặc phòng đã tồn tại.');}else{d.stt=Number(r.STT);d.studentId=String(r['Mã học sinh']);d.name=r['Họ tên'];d.className=r['Lớp'];d.id=[d.year,d.period,d.grade,d.subject,d.room,d.stt].join('|');if(demoDB.roster.some(x=>x.id===d.id||x.year===d.year&&x.period===d.period&&x.subject===d.subject&&x.studentId===d.studentId))throw Error('STT hoặc học sinh đã tồn tại.');}}
 const k=d.phone||d.id;if(seen.has(k))throw Error('Có dòng trùng trong file.');seen.add(k);items.push(d);}
 demoDB[p.kind].push(...items);demoPersist();return {count:items.length};}
 if(action==='reopen'){const r=demoDB.records.find(x=>x.id===p.id);r.status='draft';r.version++;demoDB.audit.push({time:new Date().toISOString(),actor:u.phone,action:'Mở lại phiếu',detail:{id:r.id,reason:p.reason}});demoPersist();return true;}
 if(action==='resetPassword'){const v=demoDB.users.find(x=>x.phone===p.phone);delete v.password;v.mustChange=true;demoPersist();return true;}
 if(action==='setActive'){if(p.phone===u.phone)throw Error('Không thể khóa chính mình.');demoDB.users.find(x=>x.phone===p.phone).active=p.active;demoPersist();return true;}
 if(action==='audit')return demoDB.audit.slice(-200).reverse();
 throw Error('Chức năng chưa được hỗ trợ.');
}
async function api(action,p={}){if(window.HTB_CONFIG?.mode==='live'){if(!window.HTBRemote)throw Error('Thiếu bridge.js. Hãy tải lại trang.');return window.HTBRemote(action,{...p,token:S.token});}if(NATIVE_GAS)return new Promise((resolve,reject)=>google.script.run.withSuccessHandler(r=>r.ok?resolve(r.data):reject(Error(r.error))).withFailureHandler(e=>reject(Error(e.message||e))).api(action,{...p,token:S.token}));return demoApi(action,p);}
let toastTimer;function toast(message,error=false){const el=$('#toast');el.textContent=message;el.style.background=error?'#9c4343':'#142940';el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',5000);}
function modal(html,forced=false){const m=$('#modal');m.innerHTML=html;m.oncancel=e=>{if(forced)e.preventDefault();};m.showModal();}
function closeModal(){$('#modal').close();}
function options(a,value,empty){return (empty!==undefined?`<option value="">${esc(empty)}</option>`:'')+a.map(v=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(v)}</option>`).join('');}
function initials(name){return name.split(' ').slice(-2).map(x=>x[0]).join('').toUpperCase();}
function brand(){return `<div class="brand"><div class="brand-mark"><img src="${SCHOOL_LOGO}" alt="Logo Trường THPT Hồ Thị Bi"></div><div><strong>Quản lý điểm<br>kiểm tra</strong><small>THPT HỒ THỊ BI</small></div></div>`;}
function loginScreen(){S.user=null;$('#app').innerHTML=`<main class="login"><section class="login-story">${brand()}<div class="content"><div class="eyebrow" style="color:#8aa9cb;margin-top:35px">CỔNG NHẬP ĐIỂM GIÁO VIÊN</div><h1>Mỗi bài kiểm tra.<br><span>Một kết quả chính xác.</span></h1><p>Không gian ghi điểm tập trung dành cho thầy cô. Từ nhập điểm, xác nhận phiếu đến tổng hợp báo cáo.</p><div class="mini-paper"><div class="eyebrow" style="font-size:8px;margin-bottom:12px">NĂM HỌC 2026 — 2027</div><h3>PHIẾU GHI ĐIỂM BÀI KIỂM TRA</h3><div class="line"><span>STT</span><span>Điểm minh họa</span></div><div class="line"><span>01</span><b>8,50</b></div><div class="line"><span>02</span><b>9,00</b></div><div class="line"><span>03</span><b>7,75</b></div><div style="font-size:9px;margin-top:16px;color:#768596">${icon('shield')} Ghi nhận theo tài khoản giám khảo</div></div></div><p style="font-size:9px;margin:35px 0 0;letter-spacing:1px">TRƯỜNG THPT HỒ THỊ BI · NĂM HỌC 2026 — 2027</p></section><section class="login-form-area"><div class="login-box"><div class="mobile-brand"><img src="${SCHOOL_LOGO}" alt="Logo THPT Hồ Thị Bi"></div><div class="eyebrow muted">CHÀO MỪNG THẦY CÔ</div><h2>Đăng nhập quản lý điểm kiểm tra</h2><p>Sử dụng số điện thoại đã được nhà trường cấp tài khoản để bắt đầu.</p><form id="loginForm"><div class="field"><label for="phone">Số điện thoại</label><input id="phone" name="phone" type="tel" autocomplete="username" placeholder="Nhập số điện thoại" required maxlength="15"></div><div class="field"><label for="password">Mật khẩu</label><input id="password" type="password" autocomplete="current-password" placeholder="Nhập mật khẩu" required></div><div style="display:flex;justify-content:space-between;font-size:10px"><label><input type="checkbox" id="showPassword"> Hiển thị mật khẩu</label><button type="button" class="icon-btn small" data-action="forgot">Quên mật khẩu?</button></div><div id="loginError" class="error" role="alert"></div><button class="primary" id="loginBtn">Đăng nhập ${icon('chevron')}</button></form>${!GAS?`<div class="demo-box"><h3 style="font-size:12px">Khám phá giao diện</h3><p>Dữ liệu minh họa lưu trong trình duyệt này, chưa kết nối Google Drive. Không nhập thông tin thật.</p><div class="actions"><button data-action="demo" data-role="teacher">${icon('edit')} Giáo viên</button><button data-action="demo" data-role="admin">${icon('settings')} Quản trị</button></div><p style="margin:12px 0 0">Thử đăng nhập lần đầu: 0900000001 / Htb12345@</p></div>`:''}<p class="login-foot">Mật khẩu cấp lần đầu: <b>Htb12345@</b><br>Hệ thống yêu cầu đổi mật khẩu ngay sau khi đăng nhập.</p></div></section></main>`;
 $('#showPassword').onchange=e=>$('#password').type=e.target.checked?'text':'password';$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginBtn').disabled=true;$('#loginError').textContent='';try{const r=await api('login',{phone:$('#phone').value.trim(),password:$('#password').value});S.token=r.token;S.user=r.user;if(S.user.mustChange)changePassword(true);else await boot();}catch(e){$('#loginError').textContent=e.message;}finally{if($('#loginBtn'))$('#loginBtn').disabled=false;}};
}
function changePassword(forced=false){modal(`<h2>${forced?'Đổi mật khẩu lần đầu':'Đổi mật khẩu'}</h2><p>${forced?'Chào '+esc(S.user.name)+'. Hãy đặt mật khẩu riêng trước khi nhập điểm.':'Mật khẩu mới sẽ áp dụng từ lần đăng nhập tiếp theo.'}</p><form id="changeForm"><div class="field"><label>Mật khẩu hiện tại</label><input name="old" type="password" autocomplete="current-password" required></div><div class="field"><label>Mật khẩu mới</label><input name="next" type="password" autocomplete="new-password" required minlength="10" maxlength="128"></div><div class="field"><label>Nhập lại mật khẩu mới</label><input name="again" type="password" autocomplete="new-password" required></div><p>Từ 10 ký tự, có chữ hoa, chữ thường, số và ký tự đặc biệt.</p><div id="changeError" class="error"></div><div class="modal-actions">${forced?'<button type="button" data-action="logout">Đăng xuất</button>':'<button type="button" data-action="close">Hủy</button>'}<button class="primary">Lưu mật khẩu</button></div></form>`,forced);$('#changeForm').onsubmit=async e=>{e.preventDefault();const f=e.target;if(f.next.value!==f.again.value){$('#changeError').textContent='Mật khẩu nhập lại chưa khớp.';return;}if(!validPassword(f.next.value)){$('#changeError').textContent='Mật khẩu mới chưa đủ yêu cầu hoặc trùng mật khẩu mặc định.';return;}const b=f.querySelector('.primary');b.disabled=true;try{S.user=await api('changePassword',{oldPassword:f.old.value,newPassword:f.next.value});closeModal();toast('Đã đổi mật khẩu.');if(forced)await boot();}catch(e){$('#changeError').textContent=e.message;}finally{b.disabled=false;}};}
async function boot(){const b=await api('bootstrap');S.user=b.user;S.config=b.config;S.page='entry';S.record=null;S.dirty=false;await loadData();render();}
async function loadData(){S.data=await api('list',{year:S.year,period:S.period});}
const pageInfo={entry:['Nhập điểm','Ghi điểm và xác nhận phiếu kiểm tra của thầy cô.','edit'],sheets:['Phiếu đã lưu','Theo dõi và tiếp tục các phiếu ghi điểm.','file'],scores:['Xem điểm & báo cáo','Tra cứu kết quả theo khối, môn, lớp và phòng thi.','chart'],mappings:['Quản lý số phách','Kết nối số phách với phòng thi theo từng đợt kiểm tra.','key'],rooms:['Danh sách phòng thi','Quản lý danh sách học sinh và thứ tự bài trong phòng thi.','room'],users:['Tài khoản giáo viên','Cấp tài khoản bằng số điện thoại từ danh sách Excel.','users'],settings:['Thiết lập & kết nối','Quản lý danh mục, kết nối lưu trữ và nhật ký hoạt động.','settings']};
function navButton(page){return `<button class="${S.page===page?'active':''}" data-action="nav" data-page="${page}">${icon(pageInfo[page][2])}<span>${pageInfo[page][0]}</span></button>`;}
function contextBar(){return `<div class="context"><div class="field"><label for="yearSelect">NĂM HỌC</label><select id="yearSelect">${options(S.config.years,S.year)}</select></div><div class="field"><label for="periodSelect">ĐỢT KIỂM TRA</label><select id="periodSelect">${options(S.config.periods,S.period)}</select></div>${isAdmin()?'<button class="icon-btn" data-action="addPeriod" aria-label="Thêm đợt kiểm tra" title="Thêm đợt kiểm tra">'+icon('plus')+'</button>':''}<div class="context-note">${icon('clock')} Dữ liệu được phân tách theo từng đợt kiểm tra</div></div>`;}
function render(){const p=pageInfo[S.page];$('#app').innerHTML=`<aside class="sidebar" id="appSidebar"><button class="icon-btn sidebar-close" data-action="closeMenu" aria-label="Đóng menu">${icon('close')}</button>${brand()}<div class="nav-label">KHÔNG GIAN LÀM VIỆC</div><nav class="nav">${navButton('entry')}${navButton('sheets')}${isAdmin()?navButton('scores'):''}</nav>${isAdmin()?`<div class="nav-label">QUẢN TRỊ KHẢO THÍ</div><nav class="nav">${['mappings','rooms','users','settings'].map(navButton).join('')}</nav>`:''}<div class="side-bottom"><div class="side-note"><strong>${icon(GAS?'cloud':'info')} ${GAS?'Lưu trữ Google Drive':'Không gian xem thử'}</strong>${GAS?'Dữ liệu được lưu bằng tài khoản Google của nhà trường.':'Trải nghiệm các thao tác với dữ liệu minh họa.'}</div><div class="copyright">HTB QUẢN LÝ ĐIỂM KIỂM TRA · PHIÊN BẢN 1.3</div></div></aside><div class="mobile-backdrop" data-action="closeMenu" aria-hidden="true"></div><main class="main"><header class="topbar"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Mở menu">${icon('menu')}</button><div class="breadcrumb">Khảo thí ${icon('chevron')} <b>${esc(p[0])}</b></div><div class="user-area">${!GAS?`<button class="small install-button" data-action="install" title="Cài ứng dụng" aria-label="Cài ứng dụng">${icon('download')} Cài ứng dụng</button>`:''}<div class="avatar">${esc(initials(S.user.name))}</div><div class="user-text">Xin chào, <b>${esc(S.user.name)}</b><small>${isAdmin()?'Quản trị viên':'Giáo viên'} · ${esc(S.user.phone)}</small></div><button class="icon-btn" data-action="password" title="Đổi mật khẩu" aria-label="Đổi mật khẩu">${icon('key')}</button><button class="icon-btn" data-action="logout" title="Đăng xuất" aria-label="Đăng xuất">${icon('logout')}</button></div></header><div class="page"><div class="page-head"><div><h1>${esc(p[0])}</h1><p>${esc(p[1])}</p></div><div class="head-actions">${S.page==='entry'?`<button data-action="new">${icon('plus')} Phiếu mới</button>`:`<span class="tag">${icon('shield')} ${isAdmin()?'Quản trị khảo thí':'Không gian giáo viên'}</span>`}</div></div>${!GAS?`<div class="banner"><span><b>BẢN XEM THỬ</b> · Dữ liệu minh họa trên trình duyệt, chưa lưu Google Drive.</span><a href="HTB_SO_DIEM_GOOGLE_DRIVE.zip" download>Bộ cài cho trường ${icon('download')}</a></div>`:''}${contextBar()}<section id="content"></section></div><div id="bottom"></div></main>`;$('#yearSelect').onchange=scopeChange;$('#periodSelect').onchange=scopeChange;renderContent();}
async function scopeChange(){if(S.dirty&&!confirm('Phiếu có thay đổi chưa lưu. Chuyển đợt kiểm tra?')){render();return;}S.year=$('#yearSelect').value;S.period=$('#periodSelect').value;S.record=null;S.dirty=false;S.importRows=[];S.filters={grade:'',subject:'',room:'',className:''};try{await loadData();render();}catch(e){toast(e.message,true);}}
function blankRecord(){const available=S.data.mappings[0];return {year:S.year,period:S.period,grade:available?.grade||'10',subject:available?.subject||S.config.subjects[0],phach:'',date:new Date(Date.now()+7*3600000).toISOString().slice(0,10),rows:Array.from({length:50},(_,i)=>({stt:i+1,score:null,note:''})),signature:'',version:0,status:'draft'};}
function renderContent(){if(S.page==='entry')entry();else if(S.page==='sheets')sheets();else if(S.page==='scores')scores();else if(S.page==='mappings'||S.page==='rooms')importPage();else if(S.page==='users')users();else settings();}
function entry(){if(!S.record)S.record=blankRecord();const r=S.record,locked=r.status==='confirmed'||r.owner&&r.owner!==S.user.phone;$('#content').innerHTML=`<div class="print-only" style="text-align:center">THPT HỒ THỊ BI · NĂM HỌC ${esc(S.year)} · ${esc(S.period)}</div><div class="entry-layout"><div class="card"><div class="paper-head"><div class="paper-title"><div class="paper-intro"><div class="paper-icon"><img src="${SCHOOL_LOGO}" alt="Logo trường"></div><div><div class="eyebrow">TRƯỜNG THPT HỒ THỊ BI</div><h2>PHIẾU GHI ĐIỂM BÀI KIỂM TRA</h2></div></div><span class="tag ${r.status==='confirmed'?'':'gray'}">${r.status==='confirmed'?'Đã xác nhận':'Bản nháp'}</span></div><div class="fields"><div class="field"><label for="grade">Khối</label><select id="grade" ${locked?'disabled':''}>${options(['10','11','12'],r.grade)}</select></div><div class="field"><label for="subject">Môn kiểm tra</label><select id="subject" ${locked?'disabled':''}>${options(S.config.subjects,r.subject)}</select></div><div class="field"><label for="examDate">Ngày kiểm tra</label><input type="date" id="examDate" value="${esc(r.date)}" ${locked?'disabled':''}></div><div class="field"><label for="phach">Số phách</label><input id="phach" list="phachOptions" value="${esc(r.phach)}" placeholder="Chọn / nhập phách" ${locked?'disabled':''}><datalist id="phachOptions">${phachOptions(r)}</datalist></div></div><div class="screen-only" style="margin-top:12px;display:flex;justify-content:space-between;align-items:center;gap:12px"><span style="font-size:9px;color:#8794a2">Số phách định danh một túi bài. STT từ 1–50 theo thứ tự bài.</span><button class="small" data-action="findSheet">${icon('download')} Tải phiếu</button></div></div><div class="table-toolbar"><b>Danh sách điểm kiểm tra</b><span>Thang điểm 10 <span style="margin:0 7px">·</span> 50 dòng</span></div><div class="score-wrap"><table class="scores"><thead><tr><th>STT</th><th>Điểm</th><th>Ghi chú</th></tr></thead><tbody>${r.rows.map((v,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td><input class="score" aria-label="Điểm dòng ${i+1}" data-row="${i}" inputmode="decimal" maxlength="5" placeholder="—" value="${v.score===null?'':esc(String(v.score).replace('.',','))}" ${locked?'disabled':''}></td><td><input class="note" aria-label="Ghi chú dòng ${i+1}" data-row="${i}" maxlength="300" placeholder="Thêm ghi chú nếu có…" value="${esc(v.note)}" ${locked?'disabled':''}></td></tr>`).join('')}</tbody></table></div><div class="score-footer"><span>${icon('info')} Nhấn Enter để chuyển dòng tiếp theo</span><span id="rowCount">0 / 50 đã nhập</span></div></div><aside class="stack"><div class="card progress-card"><h3>Tiến độ nhập điểm</h3><div class="counter"><span id="progressCount">0</span> <small>/ 50 bài</small></div><div class="progress-track"><div class="progress-fill" id="progressFill"></div></div><div class="progress-meta"><span><span class="dot"></span>Đã nhập điểm</span><b id="progressPercent">0%</b></div></div><div class="card signature-card"><h3>Giám khảo</h3><p>Ký và ghi rõ họ tên</p><button class="sign-upload" data-action="signature" ${locked?'disabled':''}>${r.signature?`<img src="${esc(r.signature)}" alt="Chữ ký giám khảo">`:`${icon('upload')}<span>Tải ảnh chữ ký</span><span style="font-size:8px;color:#9ca7b2">PNG, JPG · tối đa 200 KB</span>`}</button><div class="teacher-name">${esc(r.teacher||S.user.name)}</div><p style="text-align:center;margin:8px 0 0">Họ tên từ tài khoản đăng nhập</p></div><div class="hint"><h3>${icon('info')} Lưu ý khi nhập điểm</h3><p>Chấp nhận dấu chấm và dấu phẩy:<br><b>8.5 = 8,5</b><br>Điểm từ 0 đến 10. Có thể để trống các dòng chưa nhập.<br><br>Có ít nhất một điểm là lưu được. Không kiểm tra số lượng học sinh. Ảnh chữ ký được lưu cùng phiếu nếu đã tải lên.</p></div></aside></div>`;
 $('#bottom').innerHTML=`<footer class="actionbar"><div class="save-state" id="saveState">${icon('cloud')} ${r.updatedAt?'Lần lưu: '+esc(new Date(r.updatedAt).toLocaleString('vi-VN')):'Phiếu chưa được lưu'}<br><span>${GAS?'Lưu vào Google Drive của trường':'Chế độ minh họa · lưu trong trình duyệt'}</span></div><div class="actions"><button data-action="print" title="In hoặc lưu PDF">${icon('print')} In phiếu</button>${locked?`${isAdmin()&&r.status==='confirmed'?'<button data-action="reopen" class="primary">Mở lại phiếu</button>':''}`:`<button data-action="save">${icon('save')} Lưu điểm</button><button data-action="confirm" class="primary">${icon('edit')} Lưu & xác nhận</button>`}</div></footer>`;
 ['grade','subject','examDate','phach'].forEach(id=>$('#'+id).onchange=()=>{r[{examDate:'date'}[id]||id]=$('#'+id).value;S.dirty=true;if(id==='grade'||id==='subject')$('#phachOptions').innerHTML=phachOptions(r);markDirty();});
 $$('.score,.note').forEach(el=>{el.oninput=()=>{r.rows[Number(el.dataset.row)][el.classList.contains('score')?'score':'note']=el.value;S.dirty=true;if(el.classList.contains('score'))try{scoreValue(el.value);el.classList.remove('invalid');}catch{el.classList.add('invalid');}markDirty();progress();};el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const next=$$(`.${el.classList.contains('score')?'score':'note'}`)[Number(el.dataset.row)+1];next?.focus();next?.select();}};});
 $$('.score').forEach(el=>el.onpaste=e=>{const text=e.clipboardData.getData('text');if(text.includes('\n')||text.includes('\t')){e.preventDefault();const lines=text.trim().split(/\r?\n/),start=Number(el.dataset.row);if(lines.length+start>50){toast('Dữ liệu dán vượt quá 50 dòng.',true);return;}const parsed=lines.map(x=>x.split('\t'));try{parsed.forEach(x=>scoreValue(x[0]));}catch(error){toast(error.message,true);return;}parsed.forEach((x,i)=>{r.rows[start+i].score=x[0];if(x[1])r.rows[start+i].note=x[1].slice(0,300);});S.dirty=true;entry();markDirty();}});progress();
}
function phachOptions(r){return S.data.mappings.filter(m=>m.grade===r.grade&&m.subject===r.subject).map(m=>`<option value="${esc(m.phach)}"></option>`).join('');}
function progress(){const count=S.record.rows.filter(r=>r.score!==null&&r.score!==''&&(()=>{try{return scoreValue(r.score)!==null;}catch{return false;}})()).length;$('#progressCount').textContent=count;$('#progressFill').style.width=(count*2)+'%';$('#progressPercent').textContent=count*2+'%';$('#rowCount').textContent=count+' / 50 đã nhập';}
function markDirty(){if($('#saveState'))$('#saveState').innerHTML=`${icon('clock')} <b>Có thay đổi chưa lưu</b><br><span>${GAS?'Nhấn Lưu điểm để lưu vào Drive':'Nhấn Lưu điểm để lưu bản minh họa'}</span>`;}
async function saveRecord(confirming=false){if(S.busy)return;const r=S.record;try{if(!r.phach.trim())throw Error('Vui lòng chọn số phách.');if(!r.date)throw Error('Chọn ngày kiểm tra.');r.rows.forEach((x,i)=>{try{scoreValue(x.score);}catch(e){throw Error('Dòng '+(i+1)+': '+e.message);}});if(confirming){modal(`<h2>Xác nhận phiếu điểm</h2><p>Phiếu <b>${esc(r.phach)}</b> · ${esc(r.subject)} · Khối ${esc(r.grade)} sẽ được khóa sau khi lưu. Quản trị viên có thể mở lại và ghi lý do.</p><div class="note-panel">Xác nhận này sử dụng tài khoản giám khảo và ảnh chữ ký. Ảnh chữ ký đã tải lên sẽ được lưu cùng phiếu.</div><div class="modal-actions"><button data-action="close">Kiểm tra lại</button><button class="primary" data-action="finalConfirm">Xác nhận & khóa phiếu</button></div>`);return;}await persist(false);}catch(e){toast(e.message,true);}}
async function persist(confirming){if(S.busy)return;S.busy=true;$$('.actionbar button').forEach(b=>b.disabled=true);try{const result=await api('saveRecord',{...S.record,confirm:confirming,year:S.year,period:S.period});Object.assign(S.record,result);S.dirty=false;await loadData();entry();toast(GAS?'Đã lưu phiếu vào Google Drive.':'Đã lưu phiếu minh họa trong trình duyệt.');}catch(e){toast(e.message,true);}finally{S.busy=false;$$('.actionbar button').forEach(b=>b.disabled=false);}}
function empty(title,desc){return `<div class="empty">${icon('file')}<h3>${esc(title)}</h3><p>${esc(desc)}</p></div>`;}
function clearBottom(){$('#bottom').innerHTML='';}
function filterBar(includeClass=true){const all=S.data.roster,rooms=[...new Set([...all,...S.data.mappings,...S.data.records].map(x=>x.room).filter(Boolean))].sort(),classes=[...new Set(all.map(x=>x.className))].sort();return `<div class="toolbar"><div class="field"><label>Khối</label><select data-filter="grade">${options(['10','11','12'],S.filters.grade,'Tất cả khối')}</select></div><div class="field"><label>Môn kiểm tra</label><select data-filter="subject">${options(S.config.subjects,S.filters.subject,'Tất cả môn')}</select></div>${includeClass?`<div class="field"><label>Lớp</label><select data-filter="className">${options(classes,S.filters.className,'Tất cả lớp')}</select></div>`:''}<div class="field"><label>Phòng thi</label><select data-filter="room">${options(rooms,S.filters.room,'Tất cả phòng')}</select></div></div>`;}
function bindFilters(fn){$$('[data-filter]').forEach(el=>el.onchange=()=>{S.filters[el.dataset.filter]=el.value;fn();});}
function matches(r){return Object.entries(S.filters).every(([k,v])=>!v||String(r[k])===String(v));}
function sheets(){clearBottom();const rs=S.data.records.filter(r=>(!S.filters.grade||r.grade===S.filters.grade)&&(!S.filters.subject||r.subject===S.filters.subject)&&(!S.filters.room||r.room===S.filters.room));$('#content').innerHTML=`<div class="stats"><div class="stat"><small>Phiếu đã lưu</small><b>${S.data.records.length}</b><em>Trong đợt kiểm tra</em></div><div class="stat"><small>Đã xác nhận</small><b>${S.data.records.filter(r=>r.status==='confirmed').length}</b><em>Đã khóa chỉnh sửa</em></div><div class="stat"><small>Đang nhập</small><b>${S.data.records.filter(r=>r.status==='draft').length}</b><em>Có thể tiếp tục ghi điểm</em></div><div class="stat"><small>Bài có điểm</small><b>${S.data.records.reduce((n,r)=>n+r.rows.filter(x=>x.score!==null&&x.score!=='').length,0)}</b><em>Không tính dòng bỏ trống</em></div></div>${filterBar(false)}<div class="card"><div class="card-title"><h3>${isAdmin()?'Tất cả phiếu điểm':'Phiếu điểm của tôi'}</h3><span class="muted">${rs.length} phiếu</span></div>${rs.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Số phách</th><th>Khối / Môn</th><th>Giám khảo</th><th>Điểm đã nhập</th><th>Trạng thái</th><th>Cập nhật</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td class="num">${esc(r.phach)}</td><td>Khối ${esc(r.grade)} · ${esc(r.subject)}</td><td>${esc(r.teacher)}</td><td>${r.rows.filter(x=>x.score!==null&&x.score!=='').length} / 50</td><td><span class="tag ${r.status==='confirmed'?'':'amber'}">${r.status==='confirmed'?'Đã xác nhận':'Bản nháp'}</span></td><td>${new Date(r.updatedAt).toLocaleString('vi-VN')}</td><td><button class="small" data-action="openSheet" data-id="${esc(r.id)}">Mở phiếu ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có phiếu điểm','Chọn Nhập điểm để tạo và lưu phiếu đầu tiên trong đợt kiểm tra này.')}</div>`;bindFilters(sheets);}
function reportRows(){return S.data.roster.filter(matches).map(s=>{const m=S.data.mappings.find(m=>m.grade===s.grade&&m.subject===s.subject&&m.room===s.room),r=m&&S.data.records.find(r=>r.id===recordKey(m)),g=r?.rows[s.stt-1];return {...s,phach:m?.phach||'',score:g?.score??null,note:g?.note||'',teacher:r?.teacher||'',status:!m?'Chưa ghép phách':!r?'Chưa nhập':r.status==='confirmed'?'Đã xác nhận':'Bản nháp'};});}
function scores(){clearBottom();const rows=reportRows(),graded=rows.filter(r=>r.score!==null&&r.score!==''),avg=graded.length?(graded.reduce((s,r)=>s+Number(r.score),0)/graded.length).toFixed(2).replace('.',','):'—';$('#content').innerHTML=`<div class="stats"><div class="stat"><small>Lượt dự kiểm tra</small><b>${rows.length}</b><em>Theo bộ lọc đang chọn</em></div><div class="stat"><small>Đã có điểm</small><b>${graded.length}</b><em>${rows.length?Math.round(graded.length/rows.length*100):0}% danh sách</em></div><div class="stat"><small>Điểm trung bình</small><b>${avg}</b><em>Tính cả điểm 0</em></div><div class="stat"><small>Chưa có điểm</small><b>${rows.length-graded.length}</b><em>Bao gồm bài vắng</em></div></div>${filterBar()}<div class="card"><div class="card-title"><h3>Kết quả kiểm tra <span class="tag gray">${rows.length}</span></h3><button data-action="exportReport" class="primary small">${icon('download')} Xuất Excel</button></div>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>STT</th><th>Mã học sinh</th><th>Họ tên học sinh</th><th>Lớp</th><th>Môn</th><th>Phòng</th><th>Số phách</th><th>Điểm</th><th>Ghi chú</th><th>Trạng thái</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.studentId)}</td><td>${esc(r.name)}</td><td>${esc(r.className)}</td><td>${esc(r.subject)}</td><td>${esc(r.room)}</td><td>${esc(r.phach)||'—'}</td><td class="num">${r.score===null?'—':esc(String(r.score).replace('.',','))}</td><td>${esc(r.note)}</td><td><span class="tag ${r.status==='Đã xác nhận'?'':'gray'}">${esc(r.status)}</span></td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có kết quả phù hợp','Nhập danh sách phòng thi, số phách và điểm để tổng hợp báo cáo.')}</div><div class="note-panel">Ghép điểm theo năm học + đợt kiểm tra + khối + môn + số phách → phòng thi + STT. Bản nháp được ghi rõ trong báo cáo.</div>`;bindFilters(scores);}
const importDefs={users:{title:'tài khoản giáo viên',headers:['SĐT','Họ tên','Vai trò'],sample:[['0901234567','Nguyễn Văn A','teacher']],file:'MAU_TAI_KHOAN.xlsx'},mappings:{title:'số phách',headers:['Khối','Môn','Phòng','Số phách'],sample:[['10','Toán','01','10101']],file:'MAU_SO_PHACH.xlsx'},roster:{title:'danh sách phòng thi',headers:['Khối','Môn','Phòng','STT','Mã học sinh','Họ tên','Lớp'],sample:[['10','Toán','01',1,'HS001','Nguyễn Văn A','10A01']],file:'MAU_PHONG_THI.xlsx'}};
function importBox(kind){const d=importDefs[kind];return `<div class="dropzone">${icon('upload')}<h3>Nhập ${esc(d.title)} từ Excel</h3><p>Chọn file .xlsx, .xls hoặc .csv · Tối đa ${kind==='users'?'30':'1.000'} dòng / lần · 5 MB</p><button class="primary" data-action="chooseImport" data-kind="${kind}">${icon('plus')} Chọn file Excel</button><button data-action="template" data-kind="${kind}">${icon('download')} Tải file mẫu</button></div><div id="importPreview"></div>`;}
function importPage(){clearBottom();const kind=S.page==='mappings'?'mappings':'roster';S.importKind=kind;const data=S.data[kind].filter(r=>(!S.filters.grade||r.grade===S.filters.grade)&&(!S.filters.subject||r.subject===S.filters.subject)&&(!S.filters.room||r.room===S.filters.room));$('#content').innerHTML=importBox(kind)+`${filterBar(false)}<div class="card"><div class="card-title"><h3>${kind==='mappings'?'Danh sách số phách':'Học sinh trong phòng thi'} <span class="tag gray">${data.length}</span></h3><button class="small" data-action="exportList" data-kind="${kind}">${icon('download')} Xuất danh sách</button></div>${data.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${(kind==='mappings'?['Khối','Môn kiểm tra','Phòng thi','Số phách']:['Khối','Môn kiểm tra','Phòng','STT bài','Mã học sinh','Họ tên học sinh','Lớp']).map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${data.map(r=>`<tr>${(kind==='mappings'?[r.grade,r.subject,r.room,r.phach]:[r.grade,r.subject,r.room,r.stt,r.studentId,r.name,r.className]).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('Chưa có dữ liệu','Tải file mẫu, điền danh sách và nhập vào đúng năm học, đợt kiểm tra đang chọn.')}</div><div class="note-panel">${kind==='mappings'?'Mỗi số phách là một túi bài, ứng với một phòng trong cùng khối và môn. Không nhập trùng phòng hoặc số phách.':'STT từ 1–50 phải khớp thứ tự bài trên phiếu điểm. Giữ nguyên STT sau khi bắt đầu chấm để ghép điểm đúng học sinh.'} Năm học và đợt kiểm tra lấy từ bộ lọc phía trên. Dữ liệu mới được thêm, không ghi đè dữ liệu cũ.</div>`;bindFilters(importPage);}
async function users(){clearBottom();$('#content').innerHTML='<div class="loading">Đang tải danh sách tài khoản…</div>';try{S.users=await api('users');if(S.page!=='users')return;$('#content').innerHTML=importBox('users')+`<div class="note-panel">Tài khoản dùng chung giữa các năm học và đợt kiểm tra. SĐT cần định dạng Text để giữ số 0 đầu. Vai trò: <b>teacher</b> hoặc <b>admin</b>. Mật khẩu mới: <b>Htb12345@</b>, bắt buộc đổi lần đầu.</div><div class="card"><div class="card-title"><h3>Danh sách tài khoản <span class="tag gray">${S.users.length}</span></h3></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Họ tên</th><th>Số điện thoại</th><th>Vai trò</th><th>Trạng thái</th><th>Mật khẩu</th><th>Thao tác</th></tr></thead><tbody>${S.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.phone)}</td><td>${u.role==='admin'?'Quản trị viên':'Giáo viên'}</td><td><span class="tag ${u.active?'':'gray'}">${u.active?'Hoạt động':'Đã khóa'}</span></td><td>${u.mustChange?'Cần đổi lần đầu':'Đã đổi'}</td><td>${u.phone===S.user.phone?'<span class="muted">Bạn</span>':`<button class="small" data-action="resetPassword" data-phone="${esc(u.phone)}">Đặt lại</button> <button class="small" data-action="toggleUser" data-phone="${esc(u.phone)}" data-active="${!u.active}">${u.active?'Khóa':'Mở khóa'}</button>`}</td></tr>`).join('')}</tbody></table></div></div>`;}catch(e){toast(e.message,true);}}
function settings(){clearBottom();$('#content').innerHTML=`<div class="split"><div class="card card-body"><h2>${icon('cloud')} Lưu trữ & triển khai</h2><span class="tag ${GAS?'':'amber'}">${GAS?'Google Drive đang kết nối':'Chưa kết nối Google Drive'}</span><div class="setup-steps"><div class="setup-step"><div><h3>Chuẩn bị tài khoản trường</h3><p>Dùng tài khoản Google của trường để sở hữu dữ liệu và triển khai Apps Script.</p></div></div><div class="setup-step"><div><h3>Cài bộ mã nguồn</h3><p>Thêm Code.gs, Crypto.gs, Index.html. Khai báo SĐT quản trị, chạy setupSchool_ một lần và cấp quyền Drive.</p></div></div><div class="setup-step"><div><h3>Triển khai ứng dụng web</h3><p>Triển khai dưới quyền tài khoản trường. Dùng đường dẫn /exec để giáo viên đăng nhập bằng SĐT.</p></div></div></div>${!GAS?'<a href="HTB_SO_DIEM_GOOGLE_DRIVE.zip" download><button class="primary">'+icon('download')+' Tải bộ mã & hướng dẫn</button></a>':''}</div><div class="card card-body"><h2>${icon('shield')} Chữ ký trên phiếu</h2><p class="muted" style="font-size:12px;line-height:1.9">Ảnh chữ ký và họ tên giám khảo được gắn với phiếu khi xác nhận. Hệ thống lưu người thực hiện, thời gian và phiên bản phiếu.</p><div class="note-panel">Chỉ cần ít nhất một điểm hợp lệ để lưu hoặc xác nhận. Ảnh chữ ký đã tải lên được lưu cùng phiếu.</div><h3 style="margin-top:25px">Nhật ký hoạt động</h3><p class="muted" style="font-size:11px">Theo dõi các lần lưu, xác nhận và mở lại phiếu.</p><button data-action="audit">${icon('clock')} Xem nhật ký gần nhất</button></div></div><div class="card card-body section-gap"><h2>Danh mục kiểm tra</h2>${[['years','Năm học'],['periods','Đợt kiểm tra'],['subjects','Môn kiểm tra']].map(([k,t])=>`<div class="import-head"><h3 style="margin:0">${t}</h3><button class="small" data-action="addConfig" data-type="${k}">${icon('plus')} Thêm ${t.toLowerCase()}</button></div><div class="config-list">${S.config[k].map(x=>'<span>'+esc(x)+'</span>').join('')}</div>`).join('')}</div>`;}
function validateImport(kind,rows){const d=importDefs[kind],errors=[],ids=new Set(),secondary=new Set();if(!rows.length)errors.push('File chưa có dữ liệu.');if(rows.length>(kind==='users'?30:1000))errors.push('File vượt giới hạn số dòng.');rows.forEach((r,i)=>{const err=msg=>errors.push('Dòng '+(i+2)+': '+msg);for(const h of d.headers)if(r[h]===undefined||String(r[h]).trim()==='')err('Thiếu '+h);if(kind==='users'){if(!/^0\d{9}$/.test(String(r['SĐT'])))err('SĐT phải đủ 10 số, bắt đầu bằng 0.');if(!['teacher','admin'].includes(r['Vai trò']))err('Vai trò là teacher hoặc admin.');}else{if(!['10','11','12'].includes(String(r['Khối'])))err('Khối 10, 11 hoặc 12.');if(!S.config.subjects.includes(r['Môn']))err('Môn chưa có trong danh mục.');if(kind==='roster'&&(!Number.isInteger(Number(r.STT))||Number(r.STT)<1||Number(r.STT)>50))err('STT từ 1–50.');}
 const k=kind==='users'?r['SĐT']:kind==='mappings'?[r['Khối'],r['Môn'],r['Số phách']].join('|'):[r['Khối'],r['Môn'],r['Phòng'],r.STT].join('|');if(ids.has(k))err('Trùng khóa trong file.');ids.add(k);if(kind!=='users'){const k2=kind==='mappings'?[r['Khối'],r['Môn'],r['Phòng']].join('|'):[r['Môn'],r['Mã học sinh']].join('|');if(secondary.has(k2))err('Trùng phòng hoặc học sinh trong cùng môn.');secondary.add(k2);}});return {errors};}
function chooseFile(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>{if(input.files[0])callback(input.files[0]);};input.click();}
async function importFile(kind,file){try{if(file.size>5*1024*1024)throw Error('File không được vượt quá 5 MB.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellText:true});const sheet=wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false});S.importKind=kind;S.importRows=rows.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k.trim(),String(v).trim()])));const {errors}=validateImport(kind,S.importRows);const d=importDefs[kind];$('#importPreview').innerHTML=`<div class="card" style="margin-bottom:23px"><div class="card-title"><h3>Xem trước: ${esc(file.name)}</h3><span class="tag ${errors.length?'amber':''}">${rows.length} dòng · ${errors.length} lỗi</span></div><div class="card-body">${errors.length?`<div class="error">${errors.slice(0,10).map(esc).join('<br>')}${errors.length>10?'<br>…':''}</div>`:`<div class="note-panel">Sắp thêm ${rows.length} dòng vào ${esc(S.year)} · ${esc(S.period)}. Kiểm tra đúng đợt trước khi xác nhận.</div>`}<div class="table-wrap"><table class="data-table"><thead><tr>${d.headers.map(h=>'<th>'+esc(h)+'</th>').join('')}</tr></thead><tbody>${S.importRows.slice(0,8).map(r=>'<tr>'+d.headers.map(h=>'<td>'+esc(r[h])+'</td>').join('')+'</tr>').join('')}</tbody></table></div><p class="muted" style="font-size:10px;margin:14px 0">Hiển thị tối đa 8 dòng đầu. Toàn bộ file được kiểm tra trước khi nhập.</p><button class="primary" data-action="commitImport" ${errors.length?'disabled':''}>${icon('check')} Xác nhận nhập ${rows.length} dòng</button> <button data-action="cancelImport">Hủy</button></div></div>`;$('#importPreview').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){toast('Không đọc được file: '+e.message,true);}}
function xlsxDownload(headers,rows,filename,sheetName='Danh sách'){const safe=rows.map(row=>row.map(v=>typeof v==='string'&&/^[=+@-]/.test(v)?"'"+v:v));const ws=XLSX.utils.aoa_to_sheet([headers,...safe]);ws['!cols']=headers.map((h,i)=>({wch:Math.min(38,Math.max(h.length+3,...safe.slice(0,100).map(r=>String(r[i]??'').length+2)))}));ws['!autofilter']={ref:XLSX.utils.encode_range({s:{r:0,c:0},e:{r:safe.length,c:headers.length-1}})};const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,sheetName);XLSX.writeFile(wb,filename);}
function exportReport(){const rows=reportRows();if(!rows.length){toast('Không có dữ liệu để xuất.',true);return;}xlsxDownload(['Năm học','Đợt kiểm tra','Khối','Môn','Lớp','Phòng','STT bài','Mã học sinh','Họ tên','Số phách','Điểm','Ghi chú','Giám khảo','Trạng thái'],rows.map(r=>[S.year,S.period,r.grade,r.subject,r.className,r.room,r.stt,r.studentId,r.name,r.phach,r.score===null?'':Number(r.score),r.note,r.teacher,r.status]),'BAO_CAO_DIEM_'+S.period.replaceAll(' ','_')+'.xlsx','Điểm kiểm tra');}
async function findSheet(){const id=recordKey(S.record),r=S.data.records.find(x=>x.id===id);if(!r){toast('Chưa có phiếu đã lưu với số phách này. Bạn có thể nhập mới.');return;}if(S.dirty&&!confirm('Tải phiếu đã lưu và bỏ thay đổi hiện tại?'))return;S.record=await api('loadRecord',{id});S.dirty=false;entry();toast('Đã tải phiếu '+S.record.phach);}
function addConfig(type){const title={years:'năm học',periods:'đợt kiểm tra',subjects:'môn kiểm tra'}[type];modal(`<h2>Thêm ${title}</h2><form id="configForm"><div class="field"><label>Tên ${title}</label><input id="configValue" required maxlength="80" placeholder="${type==='years'?'2027 - 2028':type==='periods'?'Kiểm tra bổ sung':'Tên môn kiểm tra'}"></div><div class="modal-actions"><button type="button" data-action="close">Hủy</button><button class="primary">Thêm mới</button></div><div class="error" id="configError"></div></form>`);$('#configForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('.primary');b.disabled=true;try{const value=$('#configValue').value.trim();if(!value)throw Error('Nhập tên danh mục.');S.config=await api('addConfig',{type,value});closeModal();render();toast('Đã thêm '+title+'.');}catch(e){$('#configError').textContent=e.message;}finally{b.disabled=false;}};}
async function uploadSignature(file){try{if(!['image/png','image/jpeg'].includes(file.type)||file.size>200*1024)throw Error('Chữ ký phải là PNG/JPG tối đa 200 KB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Ảnh chữ ký không hợp lệ.'));img.src=data;});S.record.signature=data;S.dirty=true;entry();markDirty();}catch(e){toast(e.message,true);}}
async function action(e){const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{
 if(a==='close')closeModal();
 if(a==='menu'){$('.sidebar').classList.toggle('open');if($('.sidebar').classList.contains('open'))$('.sidebar-close').focus();}
 if(a==='closeMenu'){$('.sidebar').classList.remove('open');$('.mobile-toggle')?.focus();}
 if(a==='install')window.HTBInstall?.();
 if(a==='forgot')modal('<h2>Quên mật khẩu?</h2><p>Liên hệ quản trị viên nhà trường để đặt lại mật khẩu theo số điện thoại. Sau khi được đặt lại, đăng nhập bằng mật khẩu mặc định và tạo mật khẩu mới.</p><div class="modal-actions"><button data-action="close">Đã hiểu</button></div>');
 if(a==='demo'){const u=demoDB.users.find(x=>x.phone===(b.dataset.role==='admin'?'0900000002':'0900000001'));S.user=publicUser(u);S.token='demo-session';await boot();if(!S.data.records.some(r=>r.id===recordKey({...blankRecord(),phach:'10101'}))){S.record=blankRecord();S.record.phach='10101';[8.5,7,9.25,6.5,8,7.75,9,5.5].forEach((v,i)=>S.record.rows[i].score=v);S.dirty=true;entry();markDirty();}}
 if(a==='logout'){if(S.dirty&&!confirm('Có thay đổi chưa lưu. Bạn vẫn muốn đăng xuất?'))return;try{await api('logout');}catch{}closeModal();S.token='';S.dirty=false;S.record=null;loginScreen();toast('Đã đăng xuất.');}
 if(a==='password')changePassword();
 if(a==='nav'){if(S.dirty&&!confirm('Phiếu có thay đổi chưa lưu. Chuyển menu?'))return;if(S.dirty)S.record=null;S.dirty=false;S.page=b.dataset.page;S.importRows=[];await loadData();render();}
 if(a==='new'){if(S.dirty&&!confirm('Tạo phiếu mới và bỏ thay đổi hiện tại?'))return;S.record=null;S.dirty=false;entry();}
 if(a==='save')await saveRecord();
 if(a==='confirm')await saveRecord(true);
 if(a==='finalConfirm'){closeModal();await persist(true);}
 if(a==='signature')chooseFile('image/png,image/jpeg',uploadSignature);
 if(a==='print')printRecord();
 if(a==='findSheet')await findSheet();
 if(a==='openSheet'){S.record=await api('loadRecord',{id:b.dataset.id});S.page='entry';S.dirty=false;render();}
 if(a==='reopen'){modal(`<h2>Mở lại phiếu điểm</h2><p>Giám khảo sẽ được sửa phiếu. Lý do mở lại được lưu trong nhật ký.</p><form id="reopenForm"><div class="field"><label>Lý do</label><input name="reason" required maxlength="300"></div><div class="modal-actions"><button type="button" data-action="close">Hủy</button><button class="primary">Mở lại phiếu</button></div><div id="reopenError" class="error"></div></form>`);$('#reopenForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('.primary');btn.disabled=true;try{await api('reopen',{id:S.record.id,reason:e.target.reason.value});S.record=await api('loadRecord',{id:S.record.id});closeModal();await loadData();entry();toast('Đã mở lại phiếu.');}catch(e){$('#reopenError').textContent=e.message;}finally{btn.disabled=false;}};}
 if(a==='addPeriod')addConfig('periods');
 if(a==='addConfig')addConfig(b.dataset.type);
 if(a==='template'){const d=importDefs[b.dataset.kind];xlsxDownload(d.headers,d.sample,d.file,'Mau_nhap');toast('File mẫu có một dòng ví dụ. Thay bằng dữ liệu trường trước khi nhập.');}
 if(a==='chooseImport')chooseFile('.xlsx,.xls,.csv',file=>importFile(b.dataset.kind,file));
 if(a==='cancelImport'){S.importRows=[];$('#importPreview').innerHTML='';}
 if(a==='commitImport'){b.disabled=true;try{const r=await api('import',{kind:S.importKind,rows:S.importRows,year:S.year,period:S.period});S.importRows=[];await loadData();renderContent();toast('Đã nhập '+r.count+' dòng.');}finally{b.disabled=false;}}
 if(a==='exportReport')exportReport();
 if(a==='exportList'){const k=b.dataset.kind,d=importDefs[k],rows=S.data[k].filter(r=>(!S.filters.grade||r.grade===S.filters.grade)&&(!S.filters.subject||r.subject===S.filters.subject)&&(!S.filters.room||r.room===S.filters.room));xlsxDownload(['Năm học','Đợt kiểm tra',...d.headers],rows.map(r=>[S.year,S.period,...(k==='mappings'?[r.grade,r.subject,r.room,r.phach]:[r.grade,r.subject,r.room,r.stt,r.studentId,r.name,r.className])]),'DANH_SACH_'+k+'.xlsx');}
 if(a==='resetPassword'){if(!confirm('Đặt lại mật khẩu của '+b.dataset.phone+' về Htb12345@?'))return;await api('resetPassword',{phone:b.dataset.phone});await users();toast('Đã đặt lại mật khẩu và yêu cầu đổi lần đầu.');}
 if(a==='toggleUser'){if(!confirm((b.dataset.active==='true'?'Mở khóa':'Khóa')+' tài khoản '+b.dataset.phone+'?'))return;await api('setActive',{phone:b.dataset.phone,active:b.dataset.active==='true'});await users();toast('Đã cập nhật tài khoản.');}
 if(a==='audit'){const rows=await api('audit');modal(`<h2>Nhật ký hoạt động</h2><p>Tối đa 200 hoạt động gần nhất, bao gồm tất cả các đợt kiểm tra.</p><div style="max-height:400px;overflow:auto">${rows.length?rows.map(r=>`<div style="padding:14px 0;border-bottom:1px solid var(--line)"><b style="font-size:12px">${esc(r.action)}</b><p style="margin:5px 0;font-size:10px">${esc(r.actor)} · ${new Date(r.time).toLocaleString('vi-VN')}<br>${esc(JSON.stringify(r.detail))}</p></div>`).join(''):empty('Chưa có hoạt động','Các lần lưu phiếu sẽ xuất hiện ở đây.')}</div><div class="modal-actions"><button data-action="close">Đóng</button></div>`);}
 }catch(e){toast(e.message,true);}}
 document.addEventListener('click',action);window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue='';}});if(!GAS)demoInit();loginScreen();

function printRecordHtml(r){
 return [0,1].map(page=>`<section class="print-page"><header class="print-header"><img src="${SCHOOL_LOGO}" alt="Logo trường"><div><b>TRƯỜNG THPT HỒ THỊ BI</b><h2>PHIẾU GHI ĐIỂM BÀI KIỂM TRA</h2><p>Năm học: ${esc(r.year||S.year)} · Đợt: ${esc(r.period||S.period)}</p></div></header><div class="print-meta"><span>Khối: <b>${esc(r.grade)}</b></span><span>Môn KT: <b>${esc(r.subject)}</b></span><span>Ngày KT: <b>${esc(r.date)}</b></span><span>Số phách: <b>${esc(r.phach)}</b></span></div><table class="print-table"><colgroup><col style="width:12mm"><col style="width:22mm"><col></colgroup><thead><tr><th>STT</th><th>Điểm</th><th>Ghi chú</th></tr></thead><tbody>${r.rows.slice(page*25,page*25+25).map((row,i)=>`<tr><td>${page*25+i+1}</td><td>${row.score===null||row.score===''?'':esc(String(row.score).replace('.',','))}</td><td><div class="print-note" style="font-size:${String(row.note||'').length>200?5:String(row.note||'').length>120?6.5:8}pt;line-height:${String(row.note||'').length>200?1.8:String(row.note||'').length>120?2.2:2.5}mm">${esc(row.note)}</div></td></tr>`).join('')}</tbody></table><footer class="print-sign"><div><span>${r.status==='confirmed'?'Đã xác nhận':'Bản nháp'}</span><p>Trang ${page+1}/2 · STT ${page*25+1}–${page*25+25}</p></div><div class="print-examiner"><b>Giám khảo</b><small>(Ký và ghi rõ họ tên)</small>${r.signature?`<img src="${esc(r.signature)}" alt="Chữ ký giám khảo">`:'<div class="signature-space"></div>'}<strong>${esc(r.teacher||S.user.name)}</strong></div></footer></section>`).join('');
}
function printRecord(){
 let root=document.getElementById('printRoot');if(!root){root=document.createElement('div');root.id='printRoot';document.body.appendChild(root);}root.innerHTML=printRecordHtml(S.record);document.body.classList.add('printing-record');
 Promise.all(Array.from(root.querySelectorAll('img')).map(img=>img.decode?img.decode().catch(()=>{}):Promise.resolve())).then(()=>window.print());
}
window.addEventListener('afterprint',()=>document.body.classList.remove('printing-record'));
